/* Bonus-round dictionary: 3-8 letter words with no repeated letter,
   which is all the letter pool can ever spell. Grouped by length. */
(function(){var B={};
B[3]="";
B[4]="";
B[5]="";
B[6]="";
B[7]="";
B[8]="";
window.BONUS={raw:B,has:function(w){var g=B[w.length];if(!g)return false;var lo=0,hi=g.length/w.length-1;while(lo<=hi){var m=(lo+hi)>>1,s=g.substr(m*w.length,w.length);if(s===w)return true;s<w?lo=m+1:hi=m-1}return false}};})();